import { createServer, type Server } from 'node:http';
import { URL } from 'node:url';

interface CallbackResult {
  code: string;
}

interface LocalhostServerOptions {
  /** Timeout in ms before aborting. Default: 120000 */
  timeout?: number;
  /** Expected OAuth state parameter for CSRF validation */
  expectedState?: string;
}

/**
 * Inline CSS matching auth-web's design system.
 * Uses prefers-color-scheme for automatic dark mode.
 */
const PAGE_STYLES = `
  *{margin:0;padding:0;box-sizing:border-box}
  body{
    font-family:'Geist Variable',Geist,ui-sans-serif,system-ui,-apple-system,sans-serif;
    -webkit-font-smoothing:antialiased;
    -moz-osx-font-smoothing:grayscale;
    text-rendering:optimizeLegibility;
    background:#ffffff;color:#444444;
    display:flex;align-items:center;justify-content:center;
    min-height:100vh;padding:1rem;
  }
  .card{
    width:100%;max-width:28rem;
    background:#e5e5e5;border-radius:0.625rem;
    padding:2rem;box-shadow:0 10px 15px -3px rgba(0,0,0,0.1),0 4px 6px -4px rgba(0,0,0,0.1);
    text-align:center;
  }
  .logo{margin-bottom:1.5rem}
  .logo img{height:2.5rem;width:auto}
  .logo .logo-dark{display:none}
  .icon-circle{
    width:4rem;height:4rem;border-radius:50%;
    display:inline-flex;align-items:center;justify-content:center;
    margin-bottom:1rem;
  }
  .icon-circle.success{background:#dcfce7}
  .icon-circle.error{background:#fee2e2}
  .icon-circle svg{width:2rem;height:2rem}
  .icon-circle.success svg{color:#16a34a}
  .icon-circle.error svg{color:#ff5538}
  h2{font-size:1.19rem;font-weight:700;color:#444444;margin-bottom:0.5rem}
  p{font-size:0.83rem;color:#888888;line-height:1.5}
  .error-detail{
    margin-top:1rem;padding:1rem;
    background:rgba(255,85,56,0.1);border:1px solid rgba(255,85,56,0.2);
    border-radius:0.375rem;font-size:0.83rem;color:#ff5538;
  }
  @media(prefers-color-scheme:dark){
    body{background:#1e223a;color:#ffffff}
    .card{background:#2a2f4a}
    .logo .logo-light{display:none}
    .logo .logo-dark{display:block}
    h2{color:#ffffff}
    p{color:#a0a5ba}
  }
`;

const CHECK_SVG =
  '<svg fill="none" stroke="currentColor" viewBox="0 0 24 24">' +
  '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/>' +
  '</svg>';

const X_SVG =
  '<svg fill="none" stroke="currentColor" viewBox="0 0 24 24">' +
  '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>' +
  '</svg>';

/**
 * Base64-encoded Levr logos, inlined from `apps/auth-web/public/images`.
 *
 * Inlined rather than linked because this page is served by a throwaway
 * localhost server during the OAuth callback — it has no asset host to fetch
 * from, and the browser is pointed at 127.0.0.1.
 *
 * These went STALE once already. internal rebranded auth-web to Levr, and its
 * own `Logo.tsx` moved to `levr-logo-{light,dark}.png`, but this hand-pasted
 * copy kept the old `tq-logo-{light,dark}-ai.png` wordmarks — so the CLI's
 * success page still read "TestQuality AI" long after every other surface had
 * changed. The tsdown brand SCRUB could not save it either: that rewrites
 * string literals, and a wordmark inside a PNG is pixels.
 *
 * `localhost-server.logo.test.ts` now pins these to the files on disk, so the
 * next rebrand fails a test here instead of shipping in the published binary.
 */
// prettier-ignore
const LOGO_LIGHT_DATA_URI = 'data:image/png;base64,';
// prettier-ignore
const LOGO_DARK_DATA_URI = 'data:image/png;base64,';

function renderPage(
  variant: 'success' | 'error',
  title: string,
  message: string,
  detail?: string,
): string {
  const icon = variant === 'success' ? CHECK_SVG : X_SVG;
  const detailHtml = detail
    ? `<div class="error-detail">${escapeHtml(detail)}</div>`
    : '';
  return (
    '<!DOCTYPE html>' +
    '<html lang="en"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>Levr CLI</title>' +
    `<style>${PAGE_STYLES}</style>` +
    '</head><body>' +
    '<div class="card">' +
    '<div class="logo">' +
    '<img class="logo-light" src="' +
    LOGO_LIGHT_DATA_URI +
    '" alt="Levr">' +
    '<img class="logo-dark" src="' +
    LOGO_DARK_DATA_URI +
    '" alt="Levr">' +
    '</div>' +
    `<div class="icon-circle ${variant}">${icon}</div>` +
    `<h2>${escapeHtml(title)}</h2>` +
    `<p>${escapeHtml(message)}</p>` +
    detailHtml +
    '</div></body></html>'
  );
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/**
 * Start a temporary HTTP server on 127.0.0.1 with a random port.
 * Waits for an OAuth callback at /callback?code=... and returns the code.
 */
export function startCallbackServer(options: LocalhostServerOptions = {}): {
  port: Promise<number>;
  code: Promise<CallbackResult>;
  close: () => void;
} {
  const timeout = options.timeout ?? 120_000;
  const expectedState = options.expectedState;

  let resolvePort: (port: number) => void;
  let resolveCode: (result: CallbackResult) => void;
  let rejectCode: (err: Error) => void;

  const portPromise = new Promise<number>((resolve) => {
    resolvePort = resolve;
  });

  const codePromise = new Promise<CallbackResult>((resolve, reject) => {
    resolveCode = resolve;
    rejectCode = reject;
  });

  const server: Server = createServer((req, res) => {
    const url = new URL(req.url ?? '/', `http://127.0.0.1`);

    if (url.pathname === '/callback') {
      const code = url.searchParams.get('code');
      const error = url.searchParams.get('error');

      if (error) {
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(
          renderPage(
            'error',
            'Authentication failed',
            'You can close this window.',
            error,
          ),
        );
        clearTimeout(timer);
        rejectCode(new Error(`OAuth error: ${error}`));
        server.close();
        return;
      }

      if (code) {
        // Validate state parameter to prevent CSRF
        const returnedState = url.searchParams.get('state');
        if (expectedState && returnedState !== expectedState) {
          res.writeHead(200, { 'Content-Type': 'text/html' });
          res.end(
            renderPage(
              'error',
              'Authentication failed',
              'You can close this window.',
              'Invalid state parameter.',
            ),
          );
          clearTimeout(timer);
          rejectCode(new Error('OAuth state mismatch (possible CSRF)'));
          server.close();
          return;
        }

        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(
          renderPage(
            'success',
            'Authentication successful!',
            'You can close this window and return to the terminal.',
          ),
        );
        clearTimeout(timer);
        resolveCode({ code });
        server.close();
        return;
      }
    }

    res.writeHead(404);
    res.end('Not found');
  });

  const timer = setTimeout(() => {
    rejectCode(new Error('Authentication timed out. No callback received.'));
    server.close();
  }, timeout);

  server.listen(0, '127.0.0.1', () => {
    const addr = server.address();
    if (addr && typeof addr !== 'string') {
      resolvePort(addr.port);
    }
  });

  return {
    port: portPromise,
    code: codePromise,
    close: () => {
      clearTimeout(timer);
      server.close();
    },
  };
}
